/// A grid cell (x, y).
pub type Cell = (i32, i32);

/// A troll unit (SimUnit in Python).
#[derive(Clone, Debug, PartialEq)]
pub struct Unit {
    pub id: i32,
    pub player: i32,
    pub x: i32,
    pub y: i32,
    /// movement speed
    pub ms: i32,
    /// carry capacity
    pub cc: i32,
    /// harvest power
    pub hp: i32,
    /// chop power
    pub chop: i32,
    /// carried items: [PLUM, LEMON, APPLE, BANANA, IRON, WOOD]
    pub carry: [i32; 6],
}

impl Unit {
    pub fn pos(&self) -> Cell {
        (self.x, self.y)
    }
    pub fn total(&self) -> i32 {
        self.carry.iter().sum()
    }
    pub fn free(&self) -> i32 {
        self.cc - self.total()
    }
}

/// A plant / tree (SimPlant in Python).
#[derive(Clone, Debug, PartialEq)]
pub struct Plant {
    pub plant_type: String,
    pub x: i32,
    pub y: i32,
    pub size: i32,
    pub health: i32,
    pub fruits: i32,
    pub cooldown: i32,
}

impl Plant {
    pub fn pos(&self) -> Cell {
        (self.x, self.y)
    }
}

/// Full game state (GameState in Python).
#[derive(Clone, Debug)]
pub struct GameState {
    pub width: i32,
    pub height: i32,
    pub walkable: HashSet<Cell>,
    pub shacks: [Cell; 2],
    pub inventories: [[i32; 6]; 2],
    pub units: Vec<Unit>,
    pub plants: Vec<Plant>,
    pub scores: [i32; 2],
    pub turn: i32,
    pub next_id: i32,
    pub iron: HashSet<Cell>,
    pub water: HashSet<Cell>,
}

/// Parse an ASCII grid into a GameState.
///
/// Characters:
///   '.' or ' ' -> walkable
///   '#'        -> wall (not walkable, not anything else)
///   '0'        -> shack for player 0  (added to walkable)
///   '1'        -> shack for player 1  (added to walkable)
///   '+'        -> iron cell (NOT walkable, but in iron set)
///   '~'        -> water cell (NOT walkable, but in water set)
///
/// The Python from_ascii adds '0' and '1' cells to walkable implicitly
/// (they are not excluded from walkable — iron/water are excluded instead).
/// Looking at the Python: shacks go into shacks[], everything else that is
/// NOT '#' ends up in walkable or iron or water.  Actually the Python code
/// skips '#' (no else branch adds it), adds '0'/'1' as shacks, adds '+'
/// as iron, '~' as water, and everything else (including '.') to walkable.
/// So shack cells ARE in walkable (they don't go into walkable explicitly
/// but the engine uses shack as a position for units — need to check).
///
/// Re-reading Python from_ascii: the loop does `walkable.add((x,y))` only
/// in the else branch, which catches '.' and any other char not '0','1','+','~'.
/// So shack cells are NOT in walkable. Iron/water cells are NOT in walkable.
/// Only '.' (and unrecognised chars) end up in walkable.
///
/// Talents defaults: (ms=1, cc=1, hp=1, chop=0)


pub fn from_ascii_with_talents(rows: &[&str], talents: (i32, i32, i32, i32)) -> GameState {
    let height = rows.len() as i32;
    let width = if rows.is_empty() {
        0
    } else {
        rows[0].len() as i32
    };
    let mut walkable: HashSet<Cell> = HashSet::new();
    let mut iron: HashSet<Cell> = HashSet::new();
    let mut water: HashSet<Cell> = HashSet::new();
    let mut shacks: [Cell; 2] = [(0, 0), (0, 0)];

    for (y, row) in rows.iter().enumerate() {
        for (x, ch) in row.chars().enumerate() {
            let cell = (x as i32, y as i32);
            match ch {
                '0' => {
                    shacks[0] = cell;
                }
                '1' => {
                    shacks[1] = cell;
                }
                '+' => {
                    iron.insert(cell);
                }
                '~' => {
                    water.insert(cell);
                }
                '#' => { /* wall, skip */ }
                _ => {
                    walkable.insert(cell);
                }
            }
        }
    }

    let (ms, cc, hp, chop) = talents;
    let mut units = Vec::new();
    for p in 0..2i32 {
        let (sx, sy) = shacks[p as usize];
        units.push(Unit {
            id: p,
            player: p,
            x: sx,
            y: sy,
            ms,
            cc,
            hp,
            chop,
            carry: [0; 6],
        });
    }

    GameState {
        width,
        height,
        walkable,
        shacks,
        inventories: [[0; 6]; 2],
        units,
        plants: Vec::new(),
        scores: [0; 2],
        turn: 1,
        next_id: 2,
        iron,
        water,
    }
}

const PLUM:usize=0;const LEMON:usize=1;const APPLE:usize=2;
const BANANA:usize=3;const IRON:usize=4;const WOOD:usize=5;
const NEIGHBORS:[(i32,i32);4]=[(0,1),(1,0),(0,-1),(-1,0)];

pub fn item_index(name: &str) -> usize {
    match name {
        "PLUM" => PLUM,
        "LEMON" => LEMON,
        "APPLE" => APPLE,
        "BANANA" => BANANA,
        "IRON" => IRON,
        "WOOD" => WOOD,
        _ => panic!("unknown item: {}", name),
    }
}
pub fn bfs_distances(walkable: &HashSet<Cell>, sources: &[Cell]) -> HashMap<Cell, i32> {
    let mut dist: HashMap<Cell, i32> = HashMap::new();
    let mut queue: VecDeque<Cell> = VecDeque::new();
    for &cell in sources {
        if !dist.contains_key(&cell) {
            dist.insert(cell, 0);
            queue.push_back(cell);
        }
    }
    while let Some((x, y)) = queue.pop_front() {
        let d = dist[&(x, y)];
        for &(dx, dy) in &NEIGHBORS {
            let n = (x + dx, y + dy);
            if walkable.contains(&n) && !dist.contains_key(&n) {
                dist.insert(n, d + 1);
                queue.push_back(n);
            }
        }
    }
    dist
}
pub fn next_cell(walkable: &HashSet<Cell>, current: Cell, target: Cell, speed: i32) -> Cell {
    let src = bfs_distances(walkable, &[current]);

    // If target is reachable within speed, go directly
    if let Some(&d) = src.get(&target) {
        if d <= speed {
            return target;
        }
    }

    // Compute tdist: BFS from target (or nearest reachable cells if target unreachable)
    let tdist = if !src.contains_key(&target) {
        if src.is_empty() {
            return current;
        }
        let best = src.keys().map(|c| manhattan(target, *c)).min().unwrap();
        let goals: Vec<Cell> = src
            .keys()
            .filter(|c| manhattan(target, **c) == best)
            .copied()
            .collect();
        bfs_distances(walkable, &goals)
    } else {
        bfs_distances(walkable, &[target])
    };

    // Cells reachable within speed that are also in tdist
    let in_range: Vec<Cell> = src
        .iter()
        .filter(|(c, d)| **d <= speed && tdist.contains_key(*c))
        .map(|(c, _)| *c)
        .collect();

    if in_range.is_empty() {
        return current;
    }

    let best_dist = in_range.iter().map(|c| tdist[c]).min().unwrap();
    // Among ties, pick the lexicographically smallest cell (Python: min())
    in_range
        .iter()
        .filter(|c| tdist[*c] == best_dist)
        .copied()
        .min()
        .unwrap()
}
fn near_shack(game: &GameState, unit: &Unit) -> bool {
    let (sx, sy) = game.shacks[unit.player as usize];
    (unit.x - sx).abs() + (unit.y - sy).abs() <= 1
}
pub fn apply_pick(game: &mut GameState, picks: &[(i32, String)]) {
    for (uid, type_name) in picks {
        let (player, is_near, is_free) = {
            let u = match game.units.iter().find(|u| u.id == *uid) {
                Some(u) => u,
                None => continue,
            };
            (u.player as usize, near_shack(game, u), u.free() > 0)
        };
        if !is_near || !is_free {
            continue;
        }
        let idx = item_index(type_name);
        if game.inventories[player][idx] > 0 {
            game.inventories[player][idx] -= 1;
            if let Some(u) = game.units.iter_mut().find(|u| u.id == *uid) {
                u.carry[idx] += 1;
            }
        }
    }
}
pub fn training_cost(n: i32, talents: (i32, i32, i32, i32)) -> [i32; 6] {
    let (ms, cc, hp, chop) = talents;
    let mut cost = [0i32; 6];
    cost[PLUM] = n + ms * ms;
    cost[LEMON] = n + cc * cc;
    cost[APPLE] = n + hp * hp;
    cost[IRON] = n + chop * chop;
    cost
}
pub fn apply_train(game: &mut GameState, player: i32, talents: (i32, i32, i32, i32)) {
    let p = player as usize;
    let n = game.units.iter().filter(|u| u.player == player).count() as i32;
    let cost = training_cost(n, talents);
    let inv = &game.inventories[p];

    // IRON (slot 4) only charged if iron terrain present (Bronze league guard)
    let pay: &[usize] = if !game.iron.is_empty() {
        &[0, 1, 2, 3, 4, 5]
    } else {
        &[0, 1, 2, 3, 5]
    };

    // Check affordability
    if pay.iter().any(|&i| inv[i] < cost[i]) {
        return;
    }

    // Check shack is unoccupied
    let shack = game.shacks[p];
    if game.units.iter().any(|u| u.pos() == shack) {
        return;
    }

    // Deduct cost
    for &i in pay {
        game.inventories[p][i] -= cost[i];
    }

    let (ms, cc, hp, chop) = talents;
    let nid = game.next_id;
    game.units.push(Unit {
        id: nid,
        player,
        x: shack.0,
        y: shack.1,
        ms,
        cc,
        hp,
        chop,
        carry: [0; 6],
    });
    game.next_id += 1;
}
pub const TF_FULL_HEIGHT: usize = 11;
pub const TF_FULL_WIDTH: usize = 22;
pub const TF_FULL_CELLS: usize = TF_FULL_HEIGHT * TF_FULL_WIDTH;
pub const TF_FULL_OBS_SIZE: usize = 104 * TF_FULL_CELLS;
pub const TF_FULL_ACTION_SIZE: usize = 13 * TF_FULL_CELLS;
pub const TF_FULL_PLAN_SIZE: usize = 400;
pub const TF_FULL_MAX_TROLLS_PER_PLAYER: usize = 12;

const FRUIT_NAMES: [&str; 4] = ["PLUM", "LEMON", "APPLE", "BANANA"];

#[inline]
fn spatial(cell: Cell) -> usize {
    cell.1 as usize * TF_FULL_WIDTH + cell.0 as usize
}

#[inline]
fn action_index(plane: usize, cell: Cell) -> usize {
    plane * TF_FULL_CELLS + spatial(cell)
}

#[inline]
fn quant(value: i32, scale: i32) -> u8 {
    if scale <= 0 {
        return 0;
    }
    let value = value.clamp(0, scale) as f64;
    (255.0 * value / scale as f64).round() as u8
}

#[inline]
fn view_cell(game: &GameState, seat: usize, cell: Cell) -> Cell {
    if seat == 0 {
        cell
    } else {
        (game.width - 1 - cell.0, game.height - 1 - cell.1)
    }
}

#[inline]
fn absolute_cell(game: &GameState, seat: usize, cell: Cell) -> Cell {
    view_cell(game, seat, cell)
}

#[inline]
fn manhattan(left: Cell, right: Cell) -> i32 {
    (left.0 - right.0).abs() + (left.1 - right.1).abs()
}

fn own_units(game: &GameState, seat: usize) -> Vec<&Unit> {
    let mut units: Vec<_> = game
        .units
        .iter()
        .filter(|unit| unit.player as usize == seat)
        .collect();
    units.sort_by_key(|unit| unit.id);
    units
}


#[derive(Clone,Copy,Debug)]
struct StagedAction {
    troll_id: i32,
    action_index: i32,
}
#[derive(Clone,Debug)]
struct MoveRouting {
    distances: Vec<i16>,
}
impl MoveRouting {
    fn new(game: &GameState) -> Self {
        let mut distances = vec![-1; TF_FULL_CELLS * TF_FULL_CELLS];
        let mut sources: Vec<_> = game.walkable.iter().copied().collect();
        sources.extend(game.shacks);
        sources.sort_unstable();
        sources.dedup();
        for source in sources {
            for (target, distance) in bfs_distances(&game.walkable, &[source]) {
                distances[spatial(source) * TF_FULL_CELLS + spatial(target)] = distance as i16;
            }
        }
        Self { distances }
    }

    fn distance(&self, source: Cell, target: Cell) -> Option<i32> {
        let distance = self.distances[spatial(source) * TF_FULL_CELLS + spatial(target)];
        (distance >= 0).then_some(i32::from(distance))
    }

    fn next_cell(&self, game: &GameState, current: Cell, target: Cell, speed: i32) -> Cell {
        let Some(total_distance) = self.distance(current, target) else {
            return next_cell(&game.walkable, current, target, speed);
        };
        if total_distance <= speed {
            return target;
        }
        let mut best: Option<(i32, Cell)> = None;
        for y in 0..game.height {
            for x in 0..game.width {
                let candidate = (x, y);
                let Some(from_source) = self.distance(current, candidate) else {
                    continue;
                };
                if from_source > speed {
                    continue;
                }
                let Some(to_target) = self.distance(candidate, target) else {
                    continue;
                };
                let option = (to_target, candidate);
                if best.is_none_or(|current_best| option < current_best) {
                    best = Some(option);
                }
            }
        }
        best.map_or(current, |(_, cell)| cell)
    }
}
fn decode_plan(plan_index: usize) -> Option<(i32, i32, i32, i32)> {
    if plan_index >= TF_FULL_PLAN_SIZE {
        return None;
    }
    if plan_index == 0 {
        return Some((0, 0, 0, 0));
    }
    let chop = (plan_index % 5) as i32;
    let rest = plan_index / 5;
    let harvest = (rest % 4) as i32;
    let rest = rest / 4;
    let carry = (rest % 5) as i32 + 1;
    let movement = (rest / 5) as i32 + 1;
    Some((movement, carry, harvest, chop))
}

fn legal_plan_mask(game: &GameState, seat: usize, output: &mut [u8]) {
    output.fill(0);
    output[0] = 1;
    if own_units(game, seat).len() >= TF_FULL_MAX_TROLLS_PER_PLAYER {
        return;
    }
    output[1..].fill(1);
}

fn staged_game(
    game: &GameState,
    seat: usize,
    staged: &[StagedAction],
    routing: Option<&MoveRouting>,
) -> GameState {
    let mut shown = game.clone();
    for staged_action in staged {
        let index = staged_action.action_index.max(0) as usize;
        if index >= TF_FULL_ACTION_SIZE || index / TF_FULL_CELLS != 0 {
            continue;
        }
        let relative = (
            (index % TF_FULL_CELLS) % TF_FULL_WIDTH,
            (index % TF_FULL_CELLS) / TF_FULL_WIDTH,
        );
        let target = absolute_cell(game, seat, (relative.0 as i32, relative.1 as i32));
        let Some(unit) = shown
            .units
            .iter_mut()
            .find(|unit| unit.id == staged_action.troll_id && unit.player as usize == seat)
        else {
            continue;
        };
        let destination = routing.map_or_else(
            || next_cell(&game.walkable, unit.pos(), target, unit.ms),
            |routes| routes.next_cell(game, unit.pos(), target, unit.ms),
        );
        unit.x = destination.0;
        unit.y = destination.1;
    }
    shown
}

fn reserved_cells(shown: &GameState, seat: usize, staged: &[StagedAction]) -> HashSet<Cell> {
    staged
        .iter()
        .filter_map(|action| {
            shown
                .units
                .iter()
                .find(|unit| unit.id == action.troll_id && unit.player as usize == seat)
                .map(Unit::pos)
        })
        .collect()
}

fn legal_action_mask(
    game: &GameState,
    seat: usize,
    active_troll_id: i32,
    staged: &[StagedAction],
    routing: Option<&MoveRouting>,
    output: &mut [u8],
) -> Result<(), String> {
    output.fill(0);
    let shown = staged_game(game, seat, staged, routing);
    let unit = shown
        .units
        .iter()
        .find(|unit| unit.id == active_troll_id && unit.player as usize == seat)
        .ok_or_else(|| "active troll does not belong to viewing seat".to_string())?;
    let reservations = reserved_cells(&shown, seat, staged);
    let reachable = bfs_distances(&game.walkable, &[unit.pos()]);
    for &target in &game.walkable {
        if !reachable.contains_key(&target) {
            continue;
        }
        let destination = routing.map_or_else(
            || next_cell(&game.walkable, unit.pos(), target, unit.ms),
            |routes| routes.next_cell(game, unit.pos(), target, unit.ms),
        );
        if reservations.contains(&destination) {
            continue;
        }
        output[action_index(0, view_cell(game, seat, target))] = 1;
    }
    let current_view = view_cell(game, seat, unit.pos());
    let current = unit.pos();
    let current_reserved = reservations.contains(&current);
    if !current_reserved {
        output[action_index(0, current_view)] = 1;
    }
    let plant = game
        .plants
        .iter()
        .find(|plant| plant.pos() == current && plant.health > 0);
    if !current_reserved
        && unit.hp > 0
        && unit.free() > 0
        && plant.is_some_and(|plant| plant.fruits > 0)
    {
        output[action_index(1, current_view)] = 1;
    }
    if !current_reserved && unit.chop > 0 && plant.is_some() {
        output[action_index(2, current_view)] = 1;
    }
    if !current_reserved && unit.total() > 0 && manhattan(current, game.shacks[seat]) <= 1 {
        output[action_index(3, current_view)] = 1;
    }
    if !current_reserved
        && unit.chop > 0
        && unit.free() > 0
        && game.iron.iter().any(|iron| manhattan(*iron, current) == 1)
    {
        output[action_index(4, current_view)] = 1;
    }
    for kind in 0..4 {
        if !current_reserved
            && game.walkable.contains(&current)
            && !game.plants.iter().any(|plant| plant.pos() == current)
            && unit.carry[kind] > 0
        {
            output[action_index(5 + kind, current_view)] = 1;
        }
        if !current_reserved
            && unit.free() > 0
            && manhattan(current, game.shacks[seat]) <= 1
            && game.inventories[seat][kind] > 0
        {
            output[action_index(9 + kind, current_view)] = 1;
        }
    }
    if output.iter().all(|value| *value == 0) {
        output[action_index(0, current_view)] = 1;
    }
    Ok(())
}




fn set_cell(output: &mut [u8], plane: usize, cell: Cell, value: u8) {
    if cell.0 >= 0
        && cell.1 >= 0
        && (cell.0 as usize) < TF_FULL_WIDTH
        && (cell.1 as usize) < TF_FULL_HEIGHT
    {
        output[plane * TF_FULL_CELLS + spatial(cell)] = value;
    }
}

fn broadcast(output: &mut [u8], game: &GameState, plane: usize, value: u8) {
    for y in 0..game.height {
        for x in 0..game.width {
            set_cell(output, plane, (x, y), value);
        }
    }
}

fn distance_plane(
    output: &mut [u8],
    game: &GameState,
    seat: usize,
    plane: usize,
    sources: &[Cell],
) {
    let distances = bfs_distances(&game.walkable, sources);
    for y in 0..game.height {
        for x in 0..game.width {
            let cell = (x, y);
            let value = distances.get(&cell).copied().unwrap_or(40).clamp(0, 40);
            set_cell(output, plane, view_cell(game, seat, cell), quant(value, 40));
        }
    }
}

fn door_distance_plane(
    output: &mut [u8],
    game: &GameState,
    seat: usize,
    plane: usize,
    shack: Cell,
) {
    let doors: Vec<_> = game
        .walkable
        .iter()
        .copied()
        .filter(|cell| manhattan(*cell, shack) == 1)
        .collect();
    distance_plane(output, game, seat, plane, &doors);
    set_cell(output, plane, view_cell(game, seat, shack), 0);
}

fn fill_observation(
    game: &GameState,
    seat: usize,
    active_troll_id: i32,
    phase: i32,
    plan_index: usize,
    prior_target_trained: bool,
    staged: &[StagedAction],
    routing: Option<&MoveRouting>,
    output: &mut [u8],
) -> Result<(), String> {
    if output.len() != TF_FULL_OBS_SIZE || seat > 1 || !matches!(phase, 0 | 1) {
        return Err("invalid observation scalar or buffer contract".to_string());
    }
    output.fill(0);
    let shown = staged_game(game, seat, staged, routing);
    for y in 0..game.height {
        for x in 0..game.width {
            let absolute = (x, y);
            let cell = view_cell(game, seat, absolute);
            set_cell(output, 0, cell, 255);
            if game.walkable.contains(&absolute) {
                set_cell(output, 1, cell, 255);
            } else if game.water.contains(&absolute) {
                set_cell(output, 2, cell, 255);
            } else if game.iron.contains(&absolute) {
                set_cell(output, 4, cell, 255);
            } else if absolute != game.shacks[0] && absolute != game.shacks[1] {
                set_cell(output, 3, cell, 255);
            }
            if absolute == game.shacks[seat] {
                set_cell(output, 5, cell, 255);
            }
            if absolute == game.shacks[1 - seat] {
                set_cell(output, 6, cell, 255);
            }
            if game.iron.iter().any(|iron| manhattan(*iron, absolute) == 1) {
                set_cell(output, 40, cell, 255);
            }
            if game
                .water
                .iter()
                .any(|water| manhattan(*water, absolute) == 1)
            {
                set_cell(output, 41, cell, 255);
            }
        }
    }
    for plant in &game.plants {
        if plant.health <= 0 {
            continue;
        }
        let cell = view_cell(game, seat, plant.pos());
        set_cell(output, 7, cell, 255);
        if let Ok(kind) = std::panic::catch_unwind(|| item_index(&plant.plant_type)) {
            if kind < 4 {
                set_cell(output, 8 + kind, cell, 255);
            }
        }
        set_cell(output, 12, cell, quant(plant.size, 4));
        set_cell(output, 13, cell, quant(plant.health, 20));
        set_cell(output, 14, cell, quant(plant.fruits, 3));
        set_cell(output, 15, cell, quant(plant.cooldown, 9));
    }
    for unit in &shown.units {
        let own = unit.player as usize == seat;
        let cell = view_cell(game, seat, unit.pos());
        let base = if own { 18 } else { 28 };
        set_cell(output, if own { 16 } else { 17 }, cell, 255);
        set_cell(output, base, cell, quant(unit.ms, 4));
        set_cell(output, base + 1, cell, quant(unit.cc, 5));
        set_cell(output, base + 2, cell, quant(unit.hp, 3));
        set_cell(output, base + 3, cell, quant(unit.chop, 4));
        for kind in 0..6 {
            set_cell(output, base + 4 + kind, cell, quant(unit.carry[kind], 5));
        }
        set_cell(
            output,
            if own { 93 } else { 95 },
            cell,
            quant(unit.total(), 5),
        );
        set_cell(
            output,
            if own { 94 } else { 96 },
            cell,
            quant(unit.free(), 5),
        );
        let full = unit.total() == unit.cc;
        let only_nonfruit = unit.carry[PLUM..=BANANA].iter().all(|value| *value == 0);
        if full {
            set_cell(output, if own { 100 } else { 102 }, cell, 255);
            if only_nonfruit {
                set_cell(output, if own { 101 } else { 103 }, cell, 255);
            }
        }
        if own && phase == 1 && unit.id == active_troll_id {
            set_cell(output, 99, cell, 255);
        }
    }
    door_distance_plane(output, game, seat, 38, game.shacks[seat]);
    door_distance_plane(output, game, seat, 39, game.shacks[1 - seat]);
    for kind in 0..4 {
        let sources: Vec<_> = game
            .plants
            .iter()
            .filter(|plant| {
                plant.health > 0
                    && FRUIT_NAMES
                        .get(kind)
                        .is_some_and(|name| *name == plant.plant_type)
            })
            .map(Plant::pos)
            .collect();
        distance_plane(output, game, seat, 88 + kind, &sources);
    }
    let mine_sources: Vec<_> = game
        .walkable
        .iter()
        .copied()
        .filter(|cell| game.iron.iter().any(|iron| manhattan(*iron, *cell) == 1))
        .collect();
    distance_plane(output, game, seat, 92, &mine_sources);

    broadcast(output, game, 42, quant(game.turn, 300));
    for kind in 0..6 {
        broadcast(
            output,
            game,
            43 + kind,
            quant(
                game.inventories[seat][kind],
                if kind == WOOD { 128 } else { 64 },
            ),
        );
        broadcast(
            output,
            game,
            49 + kind,
            quant(
                game.inventories[1 - seat][kind],
                if kind == WOOD { 128 } else { 64 },
            ),
        );
    }
    broadcast(output, game, 55, quant(game.scores[seat], 1024));
    broadcast(output, game, 56, quant(game.scores[1 - seat], 1024));
    let ours = own_units(game, seat);
    let theirs = own_units(game, 1 - seat);
    broadcast(output, game, 57, quant(ours.len() as i32, 12));
    broadcast(output, game, 58, quant(theirs.len() as i32, 12));

    if plan_index != 0 {
        let target = decode_plan(plan_index).ok_or_else(|| "bad plan index".to_string())?;
        broadcast(output, game, 59, 255);
        broadcast(output, game, 60, quant(target.0, 4));
        broadcast(output, game, 61, quant(target.1, 5));
        broadcast(output, game, 62, quant(target.2, 3));
        broadcast(output, game, 63, quant(target.3, 4));
        let mut cost = training_cost(ours.len() as i32, target);
        if game.iron.is_empty() {
            cost[IRON] = 0;
        }
        for (offset, kind) in [PLUM, LEMON, APPLE, IRON].into_iter().enumerate() {
            broadcast(output, game, 64 + offset, quant(cost[kind], 48));
            broadcast(
                output,
                game,
                68 + offset,
                quant((cost[kind] - game.inventories[seat][kind]).max(0), 48),
            );
        }
    }
    let aggregate = |units: &[&Unit], field: fn(&Unit) -> i32| {
        (
            units.iter().map(|unit| field(unit)).max().unwrap_or(0),
            units.iter().map(|unit| field(unit)).sum::<i32>(),
        )
    };
    let fields: [fn(&Unit) -> i32; 4] = [
        |unit| unit.ms,
        |unit| unit.cc,
        |unit| unit.hp,
        |unit| unit.chop,
    ];
    let scales = [4, 5, 3, 4];
    let sum_scales = [48, 60, 36, 48];
    for (index, field) in fields.into_iter().enumerate() {
        let (own_max, own_sum) = aggregate(&ours, field);
        let (opp_max, opp_sum) = aggregate(&theirs, field);
        broadcast(output, game, 72 + index, quant(own_max, scales[index]));
        broadcast(output, game, 76 + index, quant(own_sum, sum_scales[index]));
        broadcast(output, game, 80 + index, quant(opp_max, scales[index]));
        broadcast(output, game, 84 + index, quant(opp_sum, sum_scales[index]));
    }
    if phase == 1 {
        broadcast(output, game, 97, 255);
    }
    if phase == 0 && prior_target_trained {
        broadcast(output, game, 98, 255);
    }
    Ok(())
}

fn decode_action_text(
    action: usize,
    troll_id: i32,
    seat: usize,
    width: i32,
    height: i32,
) -> Result<String, i32> {
    if action >= TF_FULL_ACTION_SIZE || seat > 1 || width <= 0 || height <= 0 {
        return Err(-2);
    }
    let plane = action / TF_FULL_CELLS;
    let cell = action % TF_FULL_CELLS;
    let x = (cell % TF_FULL_WIDTH) as i32;
    let y = (cell / TF_FULL_WIDTH) as i32;
    if x >= width || y >= height {
        return Err(-2);
    }
    let (absolute_x, absolute_y) = if seat == 0 {
        (x, y)
    } else {
        (width - 1 - x, height - 1 - y)
    };
    let text = match plane {
        0 => format!("MOVE {troll_id} {absolute_x} {absolute_y}"),
        1 => format!("HARVEST {troll_id}"),
        2 => format!("CHOP {troll_id}"),
        3 => format!("DROP {troll_id}"),
        4 => format!("MINE {troll_id}"),
        5..=8 => format!("PLANT {troll_id} {}", FRUIT_NAMES[plane - 5]),
        9..=12 => format!("PICK {troll_id} {}", FRUIT_NAMES[plane - 9]),
        _ => return Err(-2),
    };
    Ok(text)
}


struct StaticMap{rows:Vec<String>}
fn read_line(reader:&mut impl BufRead)->Option<String>{let mut line=String::new();match reader.read_line(&mut line){Ok(0)=>None,Ok(_)=>Some(line.trim_end_matches('\n').trim_end_matches('\r').to_string()),Err(_)=>None}}
fn read_static_map(reader:&mut impl BufRead)->Option<StaticMap>{let header=read_line(reader)?;let mut fields=header.split_whitespace();fields.next()?.parse::<i32>().ok()?;let height=fields.next()?.parse().ok()?;let mut rows=Vec::new();for _ in 0..height{rows.push(read_line(reader)?);}Some(StaticMap{rows})}
fn parse_stock(line:&str)->Option<[i32;6]>{let values:Vec<i32>=line.split_whitespace().map(|v|v.parse().ok()).collect::<Option<Vec<_>>>()?;values.try_into().ok()}
fn read_turn(reader:&mut impl BufRead,map:&StaticMap,turn:i32,known_seat:Option<usize>)->Option<(GameState,usize)>{
 let own=parse_stock(&read_line(reader)?)?;let other=parse_stock(&read_line(reader)?)?;
 let tree_count:usize=read_line(reader)?.parse().ok()?;let mut plants=Vec::with_capacity(tree_count);
 for _ in 0..tree_count{let line=read_line(reader)?;let f:Vec<&str>=line.split_whitespace().collect();if f.len()!=7{return None;}plants.push(Plant{plant_type:f[0].to_string(),x:f[1].parse().ok()?,y:f[2].parse().ok()?,size:f[3].parse().ok()?,health:f[4].parse().ok()?,fruits:f[5].parse().ok()?,cooldown:f[6].parse().ok()?});}
 let unit_count:usize=read_line(reader)?.parse().ok()?;let mut relative=Vec::with_capacity(unit_count);
 for _ in 0..unit_count{let line=read_line(reader)?;let v:Vec<i32>=line.split_whitespace().map(|x|x.parse().ok()).collect::<Option<Vec<_>>>()?;if v.len()!=14{return None;}relative.push(Unit{id:v[0],player:v[1],x:v[2],y:v[3],ms:v[4],cc:v[5],hp:v[6],chop:v[7],carry:[v[8],v[9],v[10],v[11],v[12],v[13]]});}
 if relative.iter().any(|u|!matches!(u.player,0|1)){return None;}
 let seat=if let Some(seat)=known_seat{seat}else{
  if turn!=1{return None;}let mut ids:Vec<i32>=relative.iter().map(|u|u.id).collect();ids.sort_unstable();
  if ids!=[0,1]{return None;}let own_ids:Vec<i32>=relative.iter().filter(|u|u.player==0).map(|u|u.id).collect();
  if own_ids.len()!=1||!matches!(own_ids[0],0|1){return None;}own_ids[0]as usize};
 let refs:Vec<&str>=map.rows.iter().map(String::as_str).collect();let mut game=from_ascii_with_talents(&refs,(1,1,1,1));
 if seat==1{game.shacks.swap(0,1);}game.inventories=if seat==0{[own,other]}else{[other,own]};
 for unit in &mut relative{if seat==1{unit.player=1-unit.player;}}game.units=relative;game.plants=plants;game.turn=turn;game.next_id=game.units.iter().map(|u|u.id).max().unwrap_or(-1)+1;
 for player in 0..2{let inv=&game.inventories[player];game.scores[player]=inv[0]+inv[1]+inv[2]+inv[3]+4*inv[WOOD];}
 Some((game,seat))}

fn decode_payload()->Vec<u8>{let mut chars=PAYLOAD_U20.chars();let mut output=Vec::with_capacity(PAYLOAD_LEN);while let Some(a)=chars.next(){let b=chars.next().unwrap();let value=(((a as u64-65536)<<20)|(b as u64-65536)).to_be_bytes();output.extend_from_slice(&value[3..]);}output.truncate(PAYLOAD_LEN);output}
fn read_f32(payload:&[u8],offset:usize)->f32{f32::from_le_bytes(payload[offset..offset+4].try_into().unwrap())}
struct Layer{o:usize,i:usize,w:Vec<f32>,b:Vec<f32>}
struct Workspace{input:Vec<f32>,hidden:Vec<f32>,scratch:Vec<f32>,residual:Vec<f32>,action:Vec<f32>}
struct Actor{conv:Vec<Layer>,linear:Vec<Layer>,null:f32,work:Workspace}
impl Actor{
 fn load(payload:&[u8],meta:&[(usize,usize,usize,usize,usize,usize,usize,usize)])->Vec<Layer>{meta.iter().map(|&(o,i,wo,ro,so,bo,bits,group)|{let mut w=Vec::with_capacity(o*i);let rb=bits-8;let groups=(i+group-1)/group;for output in 0..o{for offset in 0..i{let scale=read_f32(payload,so+4*(output*groups+offset/group));let index=output*i+offset;let bit=index*rb;let shift=bit%8;let mut residual=(payload[ro+bit/8]as usize)>>shift;if shift+rb>8{residual|=(payload[ro+bit/8+1]as usize)<<(8-shift);}residual&=(1<<rb)-1;let coarse=payload[wo+index]as i8 as i32;w.push((coarse*(1<<rb)+residual as i32)as f32*scale);}}let b=(0..o).map(|output|read_f32(payload,bo+4*output)).collect();Layer{o,i,w,b}}).collect()}
 fn new()->Self{let payload=decode_payload();let conv=Self::load(&payload,&CONV_META);let linear=Self::load(&payload,&LINEAR_META);let null=read_f32(&payload,NULL_OFFSET);Self{conv,linear,null,work:Workspace{input:vec![0.;TF_FULL_OBS_SIZE],hidden:vec![0.;16*TF_FULL_CELLS],scratch:vec![0.;16*TF_FULL_CELLS],residual:vec![0.;16*TF_FULL_CELLS],action:vec![0.;TF_FULL_ACTION_SIZE]}}}
 #[target_feature(enable="avx2")]unsafe fn convolution_range(layer:&Layer,input:&[f32],output:&mut[f32],kernel:usize,relu:bool,first:usize){let pad=kernel/2;let channels=layer.i/(kernel*kernel);for local in 0..output.len()/TF_FULL_CELLS{let oc=first+local;output[local*TF_FULL_CELLS..(local+1)*TF_FULL_CELLS].fill(layer.b[oc]);for ic in 0..channels{for ky in 0..kernel{let y0=pad.saturating_sub(ky);let y1=(TF_FULL_HEIGHT+pad-ky).min(TF_FULL_HEIGHT);for kx in 0..kernel{let x0=pad.saturating_sub(kx);let x1=(TF_FULL_WIDTH+pad-kx).min(TF_FULL_WIDTH);let weight=layer.w[((oc*channels+ic)*kernel+ky)*kernel+kx];let packed=_mm256_set1_ps(weight);let packed4=_mm_set1_ps(weight);for y in y0..y1{let ir=ic*TF_FULL_CELLS+(y+ky-pad)*TF_FULL_WIDTH;let or=local*TF_FULL_CELLS+y*TF_FULL_WIDTH;let mut x=x0;while x+8<=x1{let out=output.as_mut_ptr().add(or+x);let value=_mm256_loadu_ps(input.as_ptr().add(ir+x+kx-pad));_mm256_storeu_ps(out,_mm256_add_ps(_mm256_loadu_ps(out),_mm256_mul_ps(value,packed)));x+=8;}while x+4<=x1{let out=output.as_mut_ptr().add(or+x);let value=_mm_loadu_ps(input.as_ptr().add(ir+x+kx-pad));_mm_storeu_ps(out,_mm_add_ps(_mm_loadu_ps(out),_mm_mul_ps(value,packed4)));x+=4;}while x<x1{*output.get_unchecked_mut(or+x)+=*input.get_unchecked(ir+x+kx-pad)*weight;x+=1;}}}}}if relu{for value in &mut output[local*TF_FULL_CELLS..(local+1)*TF_FULL_CELLS]{*value=(*value).max(0.);}}}}
 fn forward(&mut self,observation:&[u8],mode:usize){for index in 0..self.work.input.len(){self.work.input[index]=observation[index]as f32*(1./255.);}unsafe{Self::convolution_range(&self.conv[0],&self.work.input,&mut self.work.hidden,3,true,0);for block in 0..4{Self::convolution_range(&self.conv[1+2*block],&self.work.hidden,&mut self.work.scratch,3,true,0);Self::convolution_range(&self.conv[2+2*block],&self.work.scratch,&mut self.work.residual,3,false,0);for index in 0..self.work.hidden.len(){self.work.hidden[index]=(self.work.hidden[index]+self.work.residual[index]).max(0.);}}if mode!=0{Self::convolution_range(&self.conv[9],&self.work.hidden,&mut self.work.action,1,false,0);}}}
 fn plane_mean(observation:&[u8],plane:usize,valid:f32)->f32{let start=plane*TF_FULL_CELLS;observation[start..start+TF_FULL_CELLS].iter().map(|value|*value as f32*(1./255.)).sum::<f32>()/valid.max(1.)}
 fn plan_logits(&self,observation:&[u8])->[f32;400]{let valid=observation[..TF_FULL_CELLS].iter().filter(|value|**value!=0).count()as f32;let mut pooled=[0f32;16];for channel in 0..16{let start=channel*TF_FULL_CELLS;let mut total=0.;for cell in 0..TF_FULL_CELLS{total+=self.work.hidden[start+cell]*(observation[cell]as f32*(1./255.));}pooled[channel]=total/valid.max(1.);}
  let banks=[43,44,45,47].map(|plane|Self::plane_mean(observation,plane,valid)*64.);let trolls=Self::plane_mean(observation,57,valid)*12.;let target=[60,61,62,63].map(|plane|Self::plane_mean(observation,plane,valid));let has_target=Self::plane_mean(observation,59,valid)>0.5;let has_iron=observation[4*TF_FULL_CELLS..5*TF_FULL_CELLS].iter().any(|value|*value!=0);let scales=[4.,5.,3.,4.];let mut logits=[0f32;400];logits[0]=self.null;
  for index in 1..400{let talents=decode_plan(index).unwrap();let raw=[talents.0 as f32,talents.1 as f32,talents.2 as f32,talents.3 as f32];let mut features=[0f32;30];features[..16].copy_from_slice(&pooled);let mut affordable=1.;let mut matches=has_target;for kind in 0..4{features[16+kind]=raw[kind]/scales[kind];let gate=if kind==3&&!has_iron{0.}else{1.};let cost=(trolls+raw[kind]*raw[kind])*gate;let deficit=(cost-banks[kind]).max(0.)*gate;features[20+kind]=cost/48.;features[24+kind]=deficit/48.;if deficit>0.{affordable=0.;}if (target[kind]*scales[kind]-raw[kind]).abs()>=0.5{matches=false;}}features[28]=affordable;features[29]=if matches{1.}else{0.};let first=&self.linear[0];let mut hidden=[0f32;32];for output in 0..32{let mut value=first.b[output];for input in 0..30{value+=features[input]*first.w[output*30+input];}hidden[output]=value.max(0.);}let second=&self.linear[1];let mut value=second.b[0];for input in 0..32{value+=hidden[input]*second.w[input];}logits[index]=value;}logits}
}
fn masked_argmax(logits:&[f32],mask:&[u8])->usize{let mut best=usize::MAX;let mut value=f32::NEG_INFINITY;for index in 0..logits.len(){if mask[index]!=0&&(best==usize::MAX||logits[index]>value){best=index;value=logits[index];}}assert_ne!(best,usize::MAX);best}
fn train_succeeds_local(game:&GameState,seat:usize,plan:usize,staged:&[StagedAction],routing:Option<&MoveRouting>)->bool{if plan==0{return false;}let mut shown=staged_game(game,seat,staged,routing);let mut picks=Vec::new();for action in staged{let index=action.action_index as usize;let plane=index/TF_FULL_CELLS;if(9..=12).contains(&plane){picks.push((action.troll_id,FRUIT_NAMES[plane-9].to_string()));}}apply_pick(&mut shown,&picks);let before=own_units(&shown,seat).len();apply_train(&mut shown,seat as i32,decode_plan(plan).unwrap());own_units(&shown,seat).len()>before}
#[cfg(tf_full_parity_probe)]
fn bytes_hex(data:&[u8])->String{const HEX:&[u8;16]=b"0123456789abcdef";let mut out=String::with_capacity(2*data.len());for value in data{out.push(HEX[(value>>4)as usize]as char);out.push(HEX[(value&15)as usize]as char);}out}
#[cfg(tf_full_parity_probe)]
fn main(){let stdin=io::stdin();let stdout=io::stdout();let mut reader=io::BufReader::new(stdin.lock());let mut output=io::BufWriter::new(stdout.lock());let Some(map)=read_static_map(&mut reader)else{return;};let Some((_,seat))=read_turn(&mut reader,&map,1,None)else{return;};let Some((game,confirmed))=read_turn(&mut reader,&map,2,Some(seat))else{return;};if confirmed!=seat{return;}let Some(config)=read_line(&mut reader)else{return;};let v:Vec<i32>=config.split_whitespace().map(|x|x.parse().ok()).collect::<Option<Vec<_>>>().unwrap_or_default();if v.len()!=6{return;}let count:usize=read_line(&mut reader).and_then(|x|x.parse().ok()).unwrap_or(usize::MAX);if count==usize::MAX{return;}let mut staged=Vec::with_capacity(count);for _ in 0..count{let Some(line)=read_line(&mut reader)else{return;};let s:Vec<i32>=line.split_whitespace().map(|x|x.parse().ok()).collect::<Option<Vec<_>>>().unwrap_or_default();if s.len()!=2{return;}staged.push(StagedAction{troll_id:s[0],action_index:s[1]});}let routes=MoveRouting::new(&game);let mut observation=vec![0u8;TF_FULL_OBS_SIZE];let mut action_mask=vec![0u8;TF_FULL_ACTION_SIZE];let mut plan_mask=[0u8;TF_FULL_PLAN_SIZE];if fill_observation(&game,seat,v[2],v[0],v[1]as usize,v[3]!=0,&staged,Some(&routes),&mut observation).is_err(){return;}if legal_action_mask(&game,seat,v[2],&staged,Some(&routes),&mut action_mask).is_err(){return;}legal_plan_mask(&game,seat,&mut plan_mask);let Ok(command)=decode_action_text(v[5]as usize,v[4],seat,game.width,game.height)else{return;};writeln!(output,"SEAT {}\nOBS {}\nACTION {}\nPLAN {}\nCOMMAND {}",seat,bytes_hex(&observation),bytes_hex(&action_mask),bytes_hex(&plan_mask),command).unwrap();output.flush().unwrap();}
#[cfg(not(tf_full_parity_probe))]
fn main(){let stdin=io::stdin();let stdout=io::stdout();let mut reader=io::BufReader::new(stdin.lock());let mut output=io::BufWriter::new(stdout.lock());let Some(map)=read_static_map(&mut reader)else{return;};let mut actor=Actor::new();let mut routing=None;let mut turn=1;let mut absolute_seat=None;while let Some((game,seat))=read_turn(&mut reader,&map,turn,absolute_seat){absolute_seat=Some(seat);if routing.is_none(){routing=Some(MoveRouting::new(&game));}let routes=routing.as_ref();let mut observation=vec![0u8;TF_FULL_OBS_SIZE];let mut action_mask=vec![0u8;TF_FULL_ACTION_SIZE];let mut plan_mask=[0u8;TF_FULL_PLAN_SIZE];let staged:Vec<StagedAction>=Vec::new();fill_observation(&game,seat,-1,0,0,false,&staged,routes,&mut observation).unwrap();for plane in 59..72{observation[plane*TF_FULL_CELLS..(plane+1)*TF_FULL_CELLS].fill(0);}observation[98*TF_FULL_CELLS..99*TF_FULL_CELLS].fill(0);legal_plan_mask(&game,seat,&mut plan_mask);actor.forward(&observation,0);let plan=masked_argmax(&actor.plan_logits(&observation),&plan_mask);let mut staged=Vec::new();let mut first=true;for unit in own_units(&game,seat){fill_observation(&game,seat,unit.id,1,plan,false,&staged,routes,&mut observation).unwrap();legal_action_mask(&game,seat,unit.id,&staged,routes,&mut action_mask).unwrap();actor.forward(&observation,if first{1}else{2});first=false;let action=masked_argmax(&actor.work.action,&action_mask);staged.push(StagedAction{troll_id:unit.id,action_index:action as i32});}let mut commands:Vec<String>=staged.iter().map(|action|decode_action_text(action.action_index as usize,action.troll_id,seat,game.width,game.height).unwrap()).collect();if train_succeeds_local(&game,seat,plan,&staged,routes){let spec=decode_plan(plan).unwrap();commands.insert(0,format!("TRAIN {} {} {} {}",spec.0,spec.1,spec.2,spec.3));}writeln!(output,"{}",commands.join(";")).unwrap();output.flush().unwrap();turn+=1;}}
